#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<int> maximumLengthOfRanges(vector<int>& nums) {
        int n=nums.size();vector<int> left(n,-1),right(n,n),st;
        for(int i=0;i<n;++i) {
            while(!st.empty()&&nums[st.back()]<=nums[i])st.pop_back();
            if(!st.empty())left[i]=st.back();
            st.push_back(i);
        }
        st.clear();
        for(int i=n-1;i>=0;--i) {
            while(!st.empty()&&nums[st.back()]<=nums[i])st.pop_back();
            if(!st.empty())right[i]=st.back();
            st.push_back(i);
        }
        vector<int> ans(n);
        for(int i=0;i<n;++i)ans[i]=right[i]-left[i]-1;
        return ans;
    }
};
